// Block (composition) — a centered maintenance message with optional icon and actions.
// Stack owns centering and spacing; this Block owns the title, description, and supplied-content structure.
import { useId, type ReactNode, type Ref } from "react";
import { Container } from "../layouts/Container";
import { Stack } from "../layouts/Stack";
import "./MaintenancePage.css";

export interface MaintenancePageProps {
  title: string;
  description?: string;
  icon?: ReactNode;
  actions?: ReactNode;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function MaintenancePage({
  title,
  description,
  icon,
  actions,
  className,
  ref,
}: MaintenancePageProps) {
  const titleId = useId();

  return (
    /* The whole page, so it takes the page frame itself: a column of the page grid, its edges on
       column lines (Container takes the grid margin and the span). */
    <Container
      as="section"
      ref={ref}
      span={{ small: 4, medium: 6, large: 6 }}
      aria-labelledby={titleId}
      className={className ? `sd-maintenancepage ${className}` : "sd-maintenancepage"}
    >
    <Stack align="center" justify="center" gap="small">
      {icon}
      {/* spacing: attachment — the glyph heads the title under it.
          The name and its supporting line are ONE unit, so they group at `x-small` while the
          page around them sits a rung looser. */}
      <Stack align="center" gap="x-small" className="sd-maintenancepage__heading">
        <h1 id={titleId} className="sd-maintenancepage__title sd-type-headline-medium">{title}</h1>
        {description && (
          <p className="sd-maintenancepage__description sd-type-body-medium">{description}</p>
        )}
      </Stack>
      {actions}
    </Stack>
    </Container>
  );
}

/* The page frame's inline half (margin, span) is the Container it renders; the block axis has no
   purpose family, so it takes a space rung. */
.sd-maintenancepage {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 100dvh;
  padding-block: var(--sd-space-medium);
  text-align: center;
}

.sd-maintenancepage__title,
.sd-maintenancepage__description {
  margin: 0;
}

.sd-maintenancepage__description {
  color: var(--sd-color-text-muted);
}
